  // ---- v0.10.5: Block 3 ----
  stAdd('RC-Modus: Gas laeuft in 2 s aus, Bremse sofort, zweiter Bremsdruck im Stand = rueckwaerts', () => {
    const f = [];
    rcZuruecksetzen();
    let t0 = 1000;
    // In 45-ms-Takten wie der Herzschlag (rcGas begrenzt einen Takt auf 200 ms).
    const schritt = (y, ms) => { let v = 0; for (let x = 0; x < ms; x += 45) { t0 += Math.min(45, ms - x); v = rcGas(y, t0); } return v; };
    schritt(1, 45);
    let v = schritt(0, 1000);
    if (!(v > 0.4 && v < 0.6)) f.push('nach 1 s ohne Gas ' + v.toFixed(2) + ' statt ~0,5');
    v = schritt(0, 1100);
    if (v !== 0) f.push('nach 2 s nicht ausgelaufen: ' + v);
    schritt(1, 45);
    v = schritt(-1, 45);
    if (!(v < 0)) f.push('Bremse greift nicht sofort');
    v = schritt(-1, 700);
    if (v !== 0) f.push('erste Bremse faehrt nach 600 ms weiter rueckwaerts: ' + v);
    schritt(0, 500);                       // loslassen, Auto "steht"
    v = schritt(-0.8, 45);                 // zweiter Druck
    if (!(v < -0.5)) f.push('zweiter Bremsdruck im Stand faehrt nicht rueckwaerts: ' + v);
    v = schritt(0, 45);
    if (v !== 0) f.push('Rueckwaerts haelt nach dem Loslassen an: ' + v);
    // v1.1.3: aus voller Fahrt bremst es, bis die Schaetzung null ist (laenger als die alten 600 ms),
    // dann Leerlauf; rueckwaerts erst mit einem neuen Druck.
    rcZuruecksetzen();
    schritt(1, 3000);
    v = schritt(-1, 400);
    if (!(v < 0)) f.push('aus voller Fahrt nach 400 ms nicht mehr gebremst: ' + v);
    v = schritt(-1, 900);
    if (v !== 0) f.push('nach dem Stillstand nicht im Leerlauf: ' + v);
    v = schritt(-1, 300);
    if (v !== 0) f.push('ohne neuen Druck rueckwaerts: ' + v);
    schritt(0, 200);
    v = schritt(-1, 45);
    if (!(v < -0.5)) f.push('neuer Druck im Stand nicht rueckwaerts: ' + v);
    rcZuruecksetzen();
    return { ok: !f.length, mass: f.length ? f.join(' | ') : 'Auslaufen 2 s, Bremse bis Stillstand, Rueckwaerts erst beim neuen Druck' };
  });

