      mp.an = true; mp.id = 'ich'; mp.frageUmgehen = false;
      mpLetzterStand = { fahrer: [{ id: 'ich', name: 'Ich' }] };
      if (mpRennenFrage() || gefragt) f.push('fragt, obwohl nur ich da bin');
