    if (fallback.rundenZurueck !== 0 || fallback.msZurueck !== 0) throw new Error('Falscher Rueckfall');
    return { ok: true, mass: 'Echte Ueberrundung, finale Rundendifferenz und gemeinsame Messrunde' };
